	if( ( $uploaded_type == "image/jpeg" || $uploaded_type == "image/png" ) &&
		( $uploaded_size < 100000 ) ) {
		if( !move_uploaded_file( $_FILES[ 'uploaded' ][ 'tmp_name' ], $target_path ) ) {", "source": "multipart/form-data 上传字段 `uploaded` 的文件名、Content-Type 与 size（$_FILES['uploaded']['name'/'type'/'size']）", "source_kind": "upload", "source_name": "uploaded", "tainted_expression": "$_FILES['uploaded']['name'] / $_FILES['uploaded']['type'] / $_FILES['uploaded']['size']", "sink": "move_uploaded_file($_FILES['uploaded']['tmp_name'], $target_path) 写入 hackable/uploads/ 目录", "endpoint": "/vulnerabilities/upload/ (045.php)", "http_method": "POST", "exploit_chain": [{"step": 1, "location": "045.php:3", "description": "检测到 POST 参数 Upload，进入上传处理分支", "data_state": "攻击者发起 multipart POST，携带 Upload 与 uploaded 文件"}, {"step": 2, "location": "045.php:5-6", "description": "拼接目标路径为 uploads 目录 + basename(原始文件名)，文件名由攻击者控制，basename 只去掉目录部分，不限制扩展名", "data_state": "$target_path = <webroot>/hackable/uploads/shell.php"}, {"step": 3, "location": "045.php:9-11", "description": "从 $_FILES 读取 name/type/size，其中 type 与 size 完全来自客户端请求", "data_state": "$uploaded_type = 'image/jpeg'（伪造），$uploaded_size = 1234（伪造）"}, {"step": 4, "location": "045.php:14-15", "description": "校验仅比较客户端声明的 MIME 与 size，伪造 Content-Type 即可通过，无扩展名白名单、无 getimagesize 内容校验", "data_state": "条件为真，进入写入分支", "bypass_reason": "Content-Type 与 size 均由客户端控制，可任意伪造；未检查文件真实内容与扩展名"}, {"step": 5, "location": "045.php:18", "description": "move_uploaded_file 把临时文件移动到 Web 可访问的 uploads 目录，保留 .php 扩展名", "data_state": "服务器上出现 <webroot>/hackable/uploads/shell.php"}, {"step": 6, "location": "045.php:24", "description": "返回上传成功信息，泄露最终路径，攻击者据此直接访问该脚本触发执行", "data_state": "响应包含 <webroot>/hackable/uploads/shell.php succesfully uploaded!"}], "poc": {"description": "伪造 Content-Type 为 image/jpeg 上传一个 PHP webshell，再访问上传后的脚本执行命令", "preconditions": ["045.php 可通过 Web 访问（DVWA upload 模块）", "hackable/uploads/ 目录可写且可被 Web 直接访问", "服务器未禁止 uploads 目录执行 PHP"], "steps": [{"step": 1, "action": "上传伪装成 JPEG 的 PHP 文件", "request": "POST /vulnerabilities/upload/ HTTP/1.1
